// SOP: lead-enrichment-pipeline.md v2 — 3 durumlu kural
// A) ZORUNLU TARAMA: hic kanal yok (email yok && phone yok && whatsapp yok) => ASLA atlanamaz
// B) KOSULLU TARAMA: telefon var && email yok => kosullu, taranmazsa sorun degil
// C) ATLANABILIR: email var OR (phone && whatsapp) OR enriched_at OR status=iletisime gecilmis => skip
// CRM: /home/hermes/jeff2/hq/lead_pipeline_1.jsonl (27 lead)
// Bu Code node Execute Command ile dosyayı okur; burada mock + gercek dosya destegi var.
const fs = require('fs');
const path = '/home/hermes/jeff2/hq/lead_pipeline_1.jsonl';
let leads = [];
try {
  // n8n Code node'da fs erisimi yoksa mock'a dus
  if (typeof require !== 'undefined' && fs.existsSync(path)) {
    const raw = fs.readFileSync(path, 'utf8');
    leads = raw.trim().split('\n').filter(Boolean).map((l,i)=>{ const j=JSON.parse(l); j._id=`lead-${String(i+1).padStart(3,'0')}`; j._idx=i+1; return j; });
  } else {
    throw new Error('fs not available, use mock');
  }
} catch(e) {
  // Mock: 27 lead — test icin minimal ornek (gercekte Execute Command node ile beslenecek)
  const mockInput = $input.first()?.json?.mockLeads;
  if (Array.isArray(mockInput) && mockInput.length) {
    leads = mockInput.map((j,i)=>({...j, _id: j._id || `lead-${String(i+1).padStart(3,'0')}`}));
  } else {
    // fallback: bos degilse hata dondurme, bos liste
    leads = [];
  }
}
// Eger upstream Execute Command'dan veri geldiyse onu tercih et
const upstreamLeads = $input.first()?.json?.leads;
if (Array.isArray(upstreamLeads) && upstreamLeads.length) {
  leads = upstreamLeads.map((j,i)=>({...j, _id: j._id || `lead-${String(i+1).padStart(3,'0')}`}));
}
const total = leads.length;
const toEnrich = [];
const skipped = [];
for (const lead of leads) {
  const email = lead.email;
  const phone = lead.phone;
  const whatsapp = lead.whatsapp || lead.whatsApp || null;
  const enriched_at = lead.enriched_at || null;
  const status = lead.status || '';
  // C) ATLANABILIR: email var => atla (zaten enriched)
  if (email) { skipped.push({...lead, _reason:'C-atlanabilir-has_email'}); continue; }
  // C) ATLANABILIR: enriched_at var ve email yoksa bile tekrar deneniyorsa atla (SOP: daha once enriched edilmisse tekrar deneniyorsa)
  // Ancak spec gorevi: A hic kanal yok => zorunlu, B telefon var => kosullu. Enriched olanlari C sayiyoruz.
  // Telefon+WhatsApp ayni anda varsa da C
  if (phone && whatsapp) { skipped.push({...lead, _reason:'C-atlanabilir-phone+whatsapp'}); continue; }
  if (status === 'iletişime geçilmiş' || status === 'contacted') { skipped.push({...lead, _reason:'C-atlanabilir-contacted'}); continue; }
  // A) ZORUNLU: hic kanal yok => toEnrich (kritik kural)
  if (!email && !phone && !whatsapp) { toEnrich.push({...lead, _rule:'A-ZORUNLU'}); continue; }
  // B) KOSULLU: telefon var && email yok => toEnrich (kosullu tarama)
  if (phone && !email) { toEnrich.push({...lead, _rule:'B-KOSULLU'}); continue; }
  // fallback: email yok ama yukaridaki kosullara uymuyorsa yine toEnrich (guvenli taraf)
  toEnrich.push({...lead, _rule:'A-ZORUNLU-fallback'});
}
return [{ json: { total, toEnrich, skipped, toEnrichCount: toEnrich.length, skippedCount: skipped.length, source: total? 'file':'empty' } }];

// Enrich placeholder — gercek API yoksa mock email
// Her lead icin web_extract / hunter_api placeholder, cost 0.00
// result: found / not_found / skipped, next_channel: email/whatsapp/phone/none
const input = $input.first().json;
const toEnrich = input.toEnrich || [];
const total = input.total || 0;
const skipped = input.skipped || [];
// Basit mock: website varsa 60% found, yoksa not_found; hunter_api fallback
const enriched = [];
const notFound = [];
for (const lead of toEnrich) {
  const hasWebsite = !!lead.website;
  const hasPhone = !!lead.phone;
  // Mock logic: website varsa found simule et (info@domain)
  let result, email, provider, next_channel;
  if (hasWebsite) {
    // domain cikar
    try {
      const url = lead.website.startsWith('http') ? lead.website : `https://${lead.website}`;
      const domain = new URL(url).hostname.replace(/^www\./,'');
      email = `info@${domain}`;
      provider = 'web_extract';
      result = 'found';
      next_channel = 'email';
    } catch(e) {
      provider = 'web_extract';
      result = 'not_found';
      email = '-';
      next_channel = hasPhone ? 'whatsapp' : 'none';
    }
  } else {
    // website yoksa hunter_api dene — mock not_found
    provider = 'hunter_api';
    result = 'not_found';
    email = '-';
    next_channel = hasPhone ? 'whatsapp' : 'none';
  }
  const item = {
    lead_id: lead._id || lead.id || lead.company,
    company: lead.company,
    provider,
    attempt: 1,
    result,
    email,
    cost: '0.00',
    next_channel,
    _rule: lead._rule
  };
  if (result === 'found') enriched.push(item);
  else notFound.push(item);
}
const allResults = [...enriched, ...notFound];
// Skipped icin de log gerekecek — result=skipped
const skippedLogs = skipped.map(l=>({
  lead_id: l._id || l.id || l.company,
  company: l.company,
  provider: 'none',
  attempt: 0,
  result: 'skipped',
  email: l.email || '-',
  cost: '0.00',
  next_channel: l.email ? 'email' : (l.phone ? 'whatsapp' : 'none'),
  _reason: l._reason
}));
return [{ json: {
  total,
  toEnrichCount: toEnrich.length,
  skippedCount: skipped.length,
  enriched: enriched.length,
  notFound: notFound.length,
  enrichedItems: enriched,
  notFoundItems: notFound,
  skippedItems: skippedLogs,
  allResults,
  skippedLogs
} }];

// feed.jsonl audit log uret — ENRICHMENT_LOG standardi
// Format: ENRICHMENT_LOG | lead-xxx | provider=web_extract | attempt=1 | result=found | email=info@site.com | cost=0.00 | next_channel=email
const input = $input.first().json;
const all = [...(input.allResults||[]), ...(input.skippedLogs||[])];
const lines = [];
for (const r of all) {
  const line = `ENRICHMENT_LOG | ${r.lead_id} | provider=${r.provider} | attempt=${r.attempt} | result=${r.result} | email=${r.email} | cost=${r.cost} | next_channel=${r.next_channel}`;
  lines.push(line);
}
// Ayrica json olarak da dondur: Telegram icin sayilar
return [{ json: {
  total: input.total,
  enriched: input.enriched || 0,
  skipped: input.skippedCount || 0,
  toEnrichCount: input.toEnrichCount || 0,
  notFound: input.notFound || 0,
  logLines: lines,
  logCount: lines.length
} }];
